      const auto group=value.toObject();if(!group["project_mode"].toBool() || (!selectedGroups.isEmpty()?!selectedGroups.contains(group["id"].toString()):(!selectedGroup.isEmpty() && group["id"].toString()!=selectedGroup)))continue;
